export const records = [{"schema_version":1,"id":"AUT-0611","slug":"public-review-policy-violation-case","title":"Контроль розгляду порушення в публічному відгуку","summary":"Опублікований відгук із можливим порушенням правил має перевірену підставу й результат розгляду; негативна оцінка сама по собі не запускає вимогу видалення.","problem":"Команда скаржиться на будь-який негативний відгук, повторює звернення або вважає статус подання доказом видалення. Рішення й допустимість оскарження губляться.","outcome":"Випадок має доказ конкретного порушення або рішення не подавати звернення; остаточний результат і фактичний показ відгуку звірені.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","owner"],"industries":["cross-industry"],"triggers":["Опублікований відгук має ознаки порушення правил платформи, які потребують перевірки."],"workflow_steps":["Зберегти ключ профілю й відгуку, актуальну редакцію та підставу підозри; приватні матеріали тримати в погодженому сховищі.","Зіставити зміст із чинною конкретною політикою; незгоду, низьку оцінку й сервісну претензію відокремити від порушення.","Погодити один належний пакет і уповноваженого заявника; невідоме авторство не називати доказом фальсифікації.","Передати звернення підтримуваним маршрутом та зберегти фактичний статус; pending не вважати видаленим відгуком.","Після відмови перевірити допустимість одноразового оскарження й нові докази; не запускати повторні звернення за таймером.","Звірити остаточне рішення та публічний стан; відгук без підтвердженого порушення лишити на належному маршруті відповіді й сервісної роботи."],"requirements":["Є актуальна редакція відгуку та конкретна застосовна політика.","Є уповноважений власник профілю й доступний маршрут стану звернення."],"limitations":["Видалення вирішує платформа; негативний відгук не є порушенням лише через незгоду компанії.","Google має одноразове оскарження та окремі правила сторонніх джерел; доступність маршруту перевіряють у цільовому випадку.","Не заявляємо автоматичного API-видалення, визначення фальшивого автора чи гарантованої зміни оцінки.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Команда скаржиться на будь-який негативний відгук, повторює звернення або вважає статус подання доказом видалення. Рішення й допустимість оскарження губляться."],"synonyms":["порушення політики публічного відгуку","статус звернення щодо відгуку","одноразове оскарження рішення про відгук"],"search_queries":["як відстежити розгляд відгуку що порушує правила без скарг на будь-яку негативну оцінку"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/business/answer/4596773?hl=en","title":"Google Business Profile: розгляд непридатних відгуків","checked_at":"2026-10-10","supports":"Описано критерій порушення політики, статуси розгляду й одноразове оскарження. Незгода з негативним відгуком не є підставою; рішення платформи звіряють із фактичним показом."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"public-review-policy-violation-case-tracked","title":"Контроль із підтвердженням результату","description":"Опублікований відгук із можливим порушенням правил має перевірену підставу й результат розгляду; негативна оцінка сама по собі не запускає вимогу видалення.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Відгук містить перевірений заборонений зміст. Власник погодив конкретну підставу, подав одне звернення та звірив рішення; низьку оцінку іншого клієнта направив на відповідь і сервісне вирішення.","implementation_methods":["Вести один випадок за ключем і редакцією відгуку з перевіреною політикою.","Контролювати стан розгляду, допустиме оскарження й фактичний публічний результат."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є актуальна редакція відгуку та конкретна застосовна політика.","Є уповноважений власник профілю й доступний маршрут стану звернення."],"limitations":["Видалення вирішує платформа; негативний відгук не є порушенням лише через незгоду компанії.","Google має одноразове оскарження та окремі правила сторонніх джерел; доступність маршруту перевіряють у цільовому випадку.","Не заявляємо автоматичного API-видалення, визначення фальшивого автора чи гарантованої зміни оцінки."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0198","reason":"Внутрішня модерація перед публікацією не вирішує долю вже опублікованого відгуку зовнішньої платформи."},{"type":"related","target_id":"AUT-0536","reason":"Доречна публічна відповідь не замінює розгляд конкретного порушення політики."},{"type":"related","target_id":"AUT-0025","reason":"Класифікація сервісної скарги не доводить порушення правил відгуків."}],"configurator_questions":[{"id":"public-review-policy-violation-case-profiles","question":"Чи звернення стосуються кількох профілів або сторонніх джерел?","help_text":"Перевірте доступність маршрутів і належність кожного джерела.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Перевірте доступність маршрутів і належність кожного джерела."}]},{"id":"public-review-policy-violation-case-appeal","question":"Чи потрібен маршрут допустимого оскарження після відмови?","help_text":"Збережіть попереднє рішення, підставу й обмеження повторного звернення.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Збережіть попереднє рішення, підставу й обмеження повторного звернення."}]}]},{"schema_version":1,"id":"AUT-0612","slug":"colleague-buyer-introduction-consent","title":"Погодження знайомства з покупцем через колегу","summary":"Продавець просить доречного колегу представити його покупцю та отримує підтверджений результат знайомства або відмову.","problem":"Продавець не знає, хто в компанії вже спілкувався з покупцем. Виявлений зв’язок помилково вважають дозволом на рекомендацію, а кілька менеджерів одночасно просять про те саме знайомство.","outcome":"Один запит має погодженого посередника, дозволений контекст і фактичний результат; припущення про знайомство не стає підтвердженим контактом.","category":"sales-crm","subcategory":"sales-operations","roles":["sales-manager","sales-representative"],"industries":["cross-industry"],"triggers":["Для конкретного покупця потрібне доречне знайомство через колегу замість повторного холодного звернення."],"workflow_steps":["Зберегти покупця, угоду або лід, мету знайомства й уже відкриті запити; не створювати повтор для іншого менеджера.","За дозволеними даними взаємодій знайти можливих колег; збіг адреси або частоту листів не прирівнювати до довіри чи готовності рекомендувати.","Уточнити актуальність зв’язку в колеги й отримати рішення щодо участі, теми та допустимого розкриття; відмову зберегти без тиску й автоматичних повторів.","Погодити короткий контекст і маршрут знайомства; колега контролює передавання контакту та запит до покупця за потрібними правилами.","Звірити фактичне знайомство, відповідь покупця або пояснену відмову; надісланий запит колезі не записувати як проведену зустріч.","Передати підтверджений контакт менеджеру з погодженою наступною дією; захистити приватні дані взаємодій від загального доступу."],"requirements":["Є перевірений запис покупця, мета запиту й відповідальний продавець.","Є дозволене джерело зв’язків і колега, який сам підтверджує актуальність та участь."],"limitations":["Підказка за взаємодіями не доводить особисту рекомендацію або згоду покупця.","Розширені підказки Dynamics залежать від джерел Exchange, доступу й ліцензії; не заявляємо аналогічну готову функцію PlanFix.","Не гарантуємо відповіді, зустрічі або виграшу угоди; приватний зміст листів не потрібен у загальній картці запиту.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Продавець не знає, хто в компанії вже спілкувався з покупцем. Виявлений зв’язок помилково вважають дозволом на рекомендацію, а кілька менеджерів одночасно просять про те саме знайомство."],"synonyms":["знайомство з покупцем через колегу","тепле представлення ліда","погоджений посередник першого контакту"],"search_queries":["як знайти колегу який може познайомити з покупцем і погодити представлення"],"sources":[{"type":"vendor_documentation","url":"https://learn.microsoft.com/en-us/dynamics365/sales/who-knows-whom","title":"Microsoft Dynamics 365: знайомство через колег","checked_at":"2026-10-10","supports":"Описано підказки зв’язків за взаємодіями, вибір колеги й редагований запит на знайомство. Базові та Exchange-дані мають різні передумови; погодження й доказ результату — редакційна модель."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"colleague-buyer-introduction-consent-tracked","title":"Контроль із підтвердженням результату","description":"Продавець просить доречного колегу представити його покупцю та отримує підтверджений результат знайомства або відмову.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Колега раніше зустрічався з покупцем, але не готовий його рекомендувати. Продавець зберіг відмову й обрав іншого доречного посередника; контакт отримав лише після погодженого представлення.","implementation_methods":["Вести один запит на знайомство з рішенням колеги й допустимим контекстом.","Добирати посередника за дозволеними даними та перевіряти фактичний результат перед наступною дією."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є перевірений запис покупця, мета запиту й відповідальний продавець.","Є дозволене джерело зв’язків і колега, який сам підтверджує актуальність та участь."],"limitations":["Підказка за взаємодіями не доводить особисту рекомендацію або згоду покупця.","Розширені підказки Dynamics залежать від джерел Exchange, доступу й ліцензії; не заявляємо аналогічну готову функцію PlanFix.","Не гарантуємо відповіді, зустрічі або виграшу угоди; приватний зміст листів не потрібен у загальній картці запиту."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0514","reason":"Учасники рішення визначають потрібного покупця, але не погоджують представлення через колегу."},{"type":"related","target_id":"AUT-0546","reason":"Контекст компанії перевіряють перед знайомством; зв’язок контакту не доводить рекомендацію."},{"type":"related","target_id":"AUT-0009","reason":"Підсумок зустрічі створюють лише після підтвердженої участі."}],"configurator_questions":[{"id":"colleague-buyer-introduction-consent-sources","question":"Чи потрібне зіставлення зв’язків із кількох дозволених джерел?","help_text":"Перевірте ключі людей, свіжість взаємодій та доступ без розкриття приватних листів.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Перевірте ключі людей, свіжість взаємодій та доступ без розкриття приватних листів."}]},{"id":"colleague-buyer-introduction-consent-teams","question":"Чи кілька команд можуть одночасно просити про знайомство з одним покупцем?","help_text":"Узгодьте власника запиту, конфлікти та повтори після відмови.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Узгодьте власника запиту, конфлікти та повтори після відмови."}]}]},{"schema_version":1,"id":"AUT-0613","slug":"new-content-digest-edition","title":"Формування дайджесту нових матеріалів без повторів","summary":"Підписники отримують погоджений випуск із новими опублікованими матеріалами; порожній або повторний випуск не запускається.","problem":"Команда вручну збирає щотижневі статті й повторно додає старі матеріали. Після збою читачам надсилають той самий випуск, а переповнена стрічка приховує пропущені статті.","outcome":"Випуск має перевірений склад нових матеріалів, пояснені пропуски та фактичний стан надсилання; попередні випуски збережені для контролю повторів.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","operations-manager"],"industries":["cross-industry"],"triggers":["Настав погоджений час перевірки нових публікацій або з’явились придатні матеріали для наступного дайджесту."],"workflow_steps":["Отримати дозволену стрічку опублікованих матеріалів і перевірити ключі, дати, посилання та доступність; чернетки не включати.","Зіставити матеріали з попередніми випусками та правилами новизни; зміна заголовка не означає нову статтю, а перепублікація потребує рішення.","Зберегти склад конкретного випуску й пояснити обмеження кількості та відкладені матеріали; недоступну стрічку не вважати порожньою.","Сформувати й перевірити заголовки, зображення та переходи в погодженому шаблоні; за відсутності нових матеріалів не створювати порожнє надсилання.","Повторно перевірити дозволену аудиторію й погодити автоматичне надсилання або редакційну чернетку; не відновлювати відписаних.","Зберегти фактичний стан випуску; при невизначеному результаті спочатку звірити відправлення, потім вирішити повтор без дублювання старого випуску."],"requirements":["Є доступна стрічка з перевіреними посиланнями на опубліковані матеріали.","Є підписники з дозволом, погоджені періодичність і правила новизни та архів випусків."],"limitations":["Brevo описує періодичну перевірку RSS, чернетку або автоматичне надсилання й обмеження складу; доступність та затримки перевіряють у цільовому сервісі.","Редакційний облік ключів, повторів і пропущених матеріалів не є заявою про гарантію доставки кожної статті штатною інтеграцією.","Успішне створення випуску не доводить доставку чи прочитання; передавання стрічки сторонньому агрегатору погоджують окремо.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Команда вручну збирає щотижневі статті й повторно додає старі матеріали. Після збою читачам надсилають той самий випуск, а переповнена стрічка приховує пропущені статті."],"synonyms":["дайджест нових матеріалів","RSS випуск розсилки","не надсилати порожній дайджест"],"search_queries":["як автоматично зібрати дайджест нових статей без старих матеріалів і повторної розсилки"],"sources":[{"type":"vendor_documentation","url":"https://help.brevo.com/hc/en-us/articles/360013130059-RSS-Campaign-integration-Automatically-share-your-blog-posts-with-your-subscribers","title":"Brevo: періодичні кампанії з RSS","checked_at":"2026-10-10","supports":"Описано перевірку стрічки, ліміт нових статей, одну контактну аудиторію на інтеграцію, пропуск без оновлень та режими чернетки й автоматичного надсилання. Облік випусків і винятків — редакційна модель."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"new-content-digest-edition-tracked","title":"Контроль із підтвердженням результату","description":"Підписники отримують погоджений випуск із новими опублікованими матеріалами; порожній або повторний випуск не запускається.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Стрічка містила більше матеріалів, ніж дозволений склад випуску. Редактор погодив вибірку й облік пропусків; після збою перевірив фактичне відправлення перед повтором.","implementation_methods":["Вести випуск як окрему редакцію зі складом матеріалів і станом відправлення.","Формувати чернетку або дозволений автоматичний випуск із перевіреної стрічки та архіву."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є доступна стрічка з перевіреними посиланнями на опубліковані матеріали.","Є підписники з дозволом, погоджені періодичність і правила новизни та архів випусків."],"limitations":["Brevo описує періодичну перевірку RSS, чернетку або автоматичне надсилання й обмеження складу; доступність та затримки перевіряють у цільовому сервісі.","Редакційний облік ключів, повторів і пропущених матеріалів не є заявою про гарантію доставки кожної статті штатною інтеграцією.","Успішне створення випуску не доводить доставку чи прочитання; передавання стрічки сторонньому агрегатору погоджують окремо."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0103","reason":"Дайджест використовує фактично опубліковані матеріали; їхній контент-план ведуть окремо."},{"type":"related","target_id":"AUT-0081","reason":"Погоджена аудиторія не визначає склад і новизну випуску."},{"type":"related","target_id":"AUT-0517","reason":"Частоту контакту перевіряють перед дозволеним надсиланням."}],"configurator_questions":[{"id":"new-content-digest-edition-feeds","question":"Чи випуск збирає матеріали з кількох стрічок?","help_text":"Погодьте ключі, порядок, дублікати й дозволений маршрут отримання.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте ключі, порядок, дублікати й дозволений маршрут отримання."}]},{"id":"new-content-digest-edition-overflow","question":"Чи потрібне окреме погодження перепублікацій та матеріалів поза лімітом?","help_text":"Визначте правила відкладення, новизни та повернення в наступний випуск.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Визначте правила відкладення, новизни та повернення в наступний випуск."}]}]},{"schema_version":1,"id":"AUT-0614","slug":"erroneous-campaign-containment","title":"Реагування на помилкову маркетингову розсилку","summary":"Команда обмежує подальшу доставку помилкового випуску, встановлює фактичне охоплення та погоджує потрібне виправлення.","problem":"Після запуску розсилки виявили неправильну умову акції. Маркетолог видаляє кампанію й вважає листи відкликаними або надсилає виправлення всім, не перевіривши фактичних одержувачів.","outcome":"Випадок має перевірений результат зупинки або її недоступність, фактичне охоплення й рішення щодо виправлення; вже доставлений зміст не оголошують відкликаним.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","owner"],"industries":["cross-industry"],"triggers":["У вже запущеному маркетинговому випуску підтверджено помилку, яка потребує рішення відповідального."],"workflow_steps":["Зберегти ключ кампанії, незмінну помилкову редакцію, час і характер помилки; визначити уповноваженого відповідального.","Перевірити фактичний стан надсилання та доступність зупинки для типу й акаунта; не обіцяти скасування вже завершеної доставки.","За погодженим терміновим правилом зупинити доступну чергу та зафіксувати команду; чекати фактичного завершення замість прирівнювання натискання до результату.","Отримати остаточні доступні дані охоплення після зупинки; зміна числа під час виконання не означає автоматично нову помилку.","Погодити зміст і придатних одержувачів виправлення або іншу потрібну дію; не дублювати акцію й не відновлювати відписку через інцидент.","Звірити фактичну корекцію, зберегти незворотні наслідки та поліпшення перевірки; розкриття приватних даних передати окремому власнику інциденту безпеки."],"requirements":["Є ключ запущеної кампанії, її редакція та доступні дані про стан і одержувачів.","Є уповноважений оператор і погоджене термінове правило зупинки та корекції."],"limitations":["Доставлений лист не можна відкликати видаленням або перейменуванням кампанії.","Mailchimp обмежує Stop Delivery типом кампанії, планом, розміром і станом надсилання; відповідність перевіряють до очікування зупинки.","Зупинка потребує часу, охоплення може збільшитися; виправлення — окремий погоджений випуск, а не редагування вже отриманих листів.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Після запуску розсилки виявили неправильну умову акції. Маркетолог видаляє кампанію й вважає листи відкликаними або надсилає виправлення всім, не перевіривши фактичних одержувачів."],"synonyms":["помилкова маркетингова розсилка","зупинка черги кампанії","виправлення вже надісланого випуску"],"search_queries":["як зупинити помилкову розсилку і визначити кому потрібне виправлення без обіцянки відкликання листів"],"sources":[{"type":"vendor_documentation","url":"https://mailchimp.com/help/cancel-a-campaign/","title":"Mailchimp: зупинка надсилання кампанії","checked_at":"2026-10-10","supports":"Описано обмежену можливість Stop Delivery, затримку зупинки та остаточний список фактичних одержувачів. Право зупинки залежить від типу, плану, розміру й стану кампанії."},{"type":"vendor_documentation","url":"https://mailchimp.com/help/why-we-cant-stop-or-edit-sent-campaigns/","title":"Mailchimp: незмінність уже надісланого змісту","checked_at":"2026-10-10","supports":"Уже переданий зміст не редагується; перейменування не змінює отриманий лист. Зупинка доступної незавершеної черги не означає відкликання доставленого."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"erroneous-campaign-containment-tracked","title":"Контроль із підтвердженням результату","description":"Команда обмежує подальшу доставку помилкового випуску, встановлює фактичне охоплення та погоджує потрібне виправлення.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Під час надсилання знайшли неправильну дату акції. Оператор зупинив доступну чергу й дочекався остаточного охоплення; власник погодив окреме уточнення для потрібної аудиторії.","implementation_methods":["Вести один випадок із доказом стану запущеної кампанії та результату доступної зупинки.","Погоджувати корекцію за фактичним охопленням, зберігаючи помилкову редакцію й незворотні наслідки."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є ключ запущеної кампанії, її редакція та доступні дані про стан і одержувачів.","Є уповноважений оператор і погоджене термінове правило зупинки та корекції."],"limitations":["Доставлений лист не можна відкликати видаленням або перейменуванням кампанії.","Mailchimp обмежує Stop Delivery типом кампанії, планом, розміром і станом надсилання; відповідність перевіряють до очікування зупинки.","Зупинка потребує часу, охоплення може збільшитися; виправлення — окремий погоджений випуск, а не редагування вже отриманих листів."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0540","reason":"Перевірка до запуску запобігає помилці, але не визначає охоплення вже запущеної кампанії."},{"type":"related","target_id":"AUT-0087","reason":"Можливе розкриття приватних даних потребує окремого реагування на інцидент безпеки."},{"type":"related","target_id":"AUT-0081","reason":"Дозвіл одержувачів перевіряють також для окремого виправлення."}],"configurator_questions":[{"id":"erroneous-campaign-containment-queues","question":"Чи один випуск має кілька незалежних черг або сервісів надсилання?","help_text":"Перевірте доступність зупинки й охоплення кожної черги окремо.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Перевірте доступність зупинки й охоплення кожної черги окремо."}]},{"id":"erroneous-campaign-containment-correction","question":"Чи потрібен окремий погоджений маршрут корекції для різних груп одержувачів?","help_text":"Визначте зміст, дозволи та перевірку фактичного виправлення.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Визначте зміст, дозволи та перевірку фактичного виправлення."}]}]},{"schema_version":1,"id":"AUT-0615","slug":"external-business-profile-change-review","title":"Розгляд сторонніх змін публічного профілю компанії","summary":"Команда звіряє запропоновані або вже застосовані сторонні зміни профілю з фактичними даними бізнесу та підтверджує публічний результат.","problem":"Платформа змінила телефон чи адресу за зовнішніми відомостями, а власник не помітив розбіжності. Старий масовий файл випадково замінює потрібні дані або не скасовує небажане оновлення.","outcome":"Кожна суттєва стороння зміна має перевірену підставу, рішення відповідального й фактичний публічний стан; непрочитане повідомлення не стає схваленням команди.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","operations-manager"],"industries":["cross-industry"],"triggers":["Надійшло повідомлення про сторонню правку або виявлено розбіжність публічного профілю з підтвердженими відомостями."],"workflow_steps":["Зберегти ключ профілю, поле, старе й запропоноване або вже показане значення, джерело сигналу та час; не змішувати різні філії.","Уточнити фактичні дані у відповідального бізнесу й зіставити стан правки: очікує рішення чи вже застосована; не вважати всі зміни попередньо погоджуваними.","Передати суттєву правку власнику з доступним строком відповіді; невідоме джерело не оголошувати зловмисником без доказу.","Уповноважений оператор приймає, відхиляє або виправляє дані підтримуваним маршрутом; перед масовим файлом перевіряє вплив змінених, незмінних і порожніх полів.","Прочитати фактичний стан та публічне відображення після обробки; заявку чи збереження не називати гарантією показу.","Зберегти рішення й відкриту розбіжність; повторний зовнішній сигнал звірити з актуальною редакцією без сліпого перезаписування всіх даних."],"requirements":["Є ключ профілю, дозволений доступ і відповідальний за фактичні відомості бізнесу.","Є джерело контрольних значень та маршрут сигналів і ручної перевірки показу."],"limitations":["Google може застосувати окремі правки без попереднього розгляду; не всі оновлення керуються з профілю.","Строк доступного рішення беруть із актуального повідомлення; не обіцяємо запобігання всім стороннім змінам.","Погодження в локальній задачі не підтверджує приймання платформою або фактичний показ.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Платформа змінила телефон чи адресу за зовнішніми відомостями, а власник не помітив розбіжності. Старий масовий файл випадково замінює потрібні дані або не скасовує небажане оновлення."],"synonyms":["стороння зміна профілю компанії","неправильний телефон у публічному профілі","розгляд запропонованої правки Google"],"search_queries":["як помічати сторонні зміни телефону або адреси компанії в Google і перевіряти виправлення"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/business/answer/3480441?hl=en","title":"Google Business Profile: сторонні оновлення відомостей","checked_at":"2026-10-10","supports":"Описано різні джерела оновлень, обмежений попередній розгляд і вплив масових файлів. Окремі зміни застосовуються без попереднього погодження; облік рішень — редакційна модель."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"external-business-profile-change-review-tracked","title":"Контроль із підтвердженням результату","description":"Команда звіряє запропоновані або вже застосовані сторонні зміни профілю з фактичними даними бізнесу та підтверджує публічний результат.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Профіль показав старий телефон після сторонньої правки. Керівник філії підтвердив актуальний номер; оператор виправив потрібне поле й перевірив фактичний показ без зміни сусідніх філій.","implementation_methods":["Вести випадок за профілем, полем і редакцією з перевіреним рішенням.","Зіставляти сигнали та публічний показ із фактичними відомостями й контролювати результат дозволеної правки."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є ключ профілю, дозволений доступ і відповідальний за фактичні відомості бізнесу.","Є джерело контрольних значень та маршрут сигналів і ручної перевірки показу."],"limitations":["Google може застосувати окремі правки без попереднього розгляду; не всі оновлення керуються з профілю.","Строк доступного рішення беруть із актуального повідомлення; не обіцяємо запобігання всім стороннім змінам.","Погодження в локальній задачі не підтверджує приймання платформою або фактичний показ."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0537","reason":"Погоджений графік є контрольним джерелом, але не замінює розгляд стороннього оновлення."},{"type":"related","target_id":"AUT-0608","reason":"Стороння правка чинного профілю не є доказом дубля бізнесу."}],"configurator_questions":[{"id":"external-business-profile-change-review-locations","question":"Чи потрібна перевірка кількох філій або масових файлів?","help_text":"Зіставте ключі та вплив полів, щоб не перезаписати іншу філію.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Зіставте ключі та вплив полів, щоб не перезаписати іншу філію."}]},{"id":"external-business-profile-change-review-owners","question":"Чи різні власники підтверджують телефон, адресу та інші відомості?","help_text":"Узгодьте строки, суперечливі джерела й рішення щодо вже застосованої правки.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Узгодьте строки, суперечливі джерела й рішення щодо вже застосованої правки."}]}]},{"schema_version":1,"id":"AUT-0616","slug":"post-decision-buyer-interview-evidence","title":"Збір причин рішення покупця через інтерв’ю","summary":"Команда отримує добровільний відгук покупців після завершеного вибору та пов’язує висновки з доказами й рішеннями для поліпшення продажів.","problem":"Причину закритої угоди записав продавець, але покупець прийняв рішення з інших підстав. На дослідження запрошують лише зручних клієнтів, а окрему цитату називають законом для всіх продажів.","outcome":"Програма має пояснену вибірку, фактичну участь, дозволені свідчення покупців і висновки з межами; відповідальні погоджують дії без підміни слів покупця припущеннями.","category":"sales-crm","subcategory":"sales-operations","roles":["sales-manager","sales-representative"],"industries":["cross-industry"],"triggers":["Завершився вибір покупця й угода потрапила до погодженої вибірки дослідження виграних та програних продажів."],"workflow_steps":["Сформувати вибірку завершених рішень за погодженими критеріями, включаючи виграні та програні угоди; зберегти виключення й підстави без відбору лише схвальних покупців.","Погодити контакт із власником відносин та участь із покупцем; відмову врахувати в охопленні й зупинити повтори за правилами.","Підготувати нейтральні відкриті теми та доречного інтерв’юера; не перетворювати розмову на спробу відновити продаж або підтвердити причину продавця.","Після фактичної розмови зберегти дозволені нотатки чи погоджений запис, контекст ролі й точні підстави висновків; припущення та слова покупця розділити.","Зіставити теми між інтерв’ю та кодами угод, відокремити суперечності й неучасть; якісну вибірку не подавати як статистично репрезентативний результат.","Передати короткі висновки з доказами й межами власникам продукту, маркетингу або продажів; зберегти погоджені дії та перевірити їх виконання окремо від проведення інтерв’ю."],"requirements":["Є завершені угоди, погоджені критерії вибірки й дозволений маршрут запрошення.","Є інтерв’юер, правила згоди й зберігання свідчень та власники наступних рішень."],"limitations":["Інтерв’ю дає повідомлення покупця, а не незалежну перевірку всіх його тверджень про конкурентів.","Наявність запису чи цитати не доводить причинний вплив на всі продажі; відмови й вибірковість пояснюють.","Години оцінюють налаштування контрольного процесу, а не роботу інтерв’юера для необмеженої кількості розмов.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Причину закритої угоди записав продавець, але покупець прийняв рішення з інших підстав. На дослідження запрошують лише зручних клієнтів, а окрему цитату називають законом для всіх продажів."],"synonyms":["інтерв’ю після рішення покупця","порівняти причину продавця зі словами покупця","дослідження виграних і програних угод"],"search_queries":["як отримати реальні причини рішення покупця після виграної або програної угоди через інтервю"],"sources":[{"type":"vendor_documentation","url":"https://www.clozd.com/guides/win-loss-interviews","title":"Clozd: інтерв’ю після виграних і програних рішень","checked_at":"2026-10-10","supports":"Авторський методичний посібник описує відбір, погодження контакту, нейтральні відкриті теми та підсумки з доказами. Це рекомендації постачальника, не доказ результатів CRMCUSTOMS або репрезентативності вибірки."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"post-decision-buyer-interview-evidence-tracked","title":"Контроль із підтвердженням результату","description":"Команда отримує добровільний відгук покупців після завершеного вибору та пов’язує висновки з доказами й рішеннями для поліпшення продажів.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Продавець указав ціну як причину втрати. Покупець у добровільній розмові пояснив інший критерій; команда зберегла свідчення, перевірила тему в інших розмовах і погодила потрібну дію.","implementation_methods":["Вести вибірку, запрошення, дозволені свідчення й тематичні висновки як окрему програму.","Пов’язувати висновки з угодами та погодженими діями, зберігаючи суперечності й межі доказів."],"complexity":"medium","hours_min":22,"hours_max":44,"requirements":["Є завершені угоди, погоджені критерії вибірки й дозволений маршрут запрошення.","Є інтерв’юер, правила згоди й зберігання свідчень та власники наступних рішень."],"limitations":["Інтерв’ю дає повідомлення покупця, а не незалежну перевірку всіх його тверджень про конкурентів.","Наявність запису чи цитати не доводить причинний вплив на всі продажі; відмови й вибірковість пояснюють.","Години оцінюють налаштування контрольного процесу, а не роботу інтерв’юера для необмеженої кількості розмов."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0011","reason":"Код причини продавця є порівнюваним джерелом, а не підтвердженою відповіддю покупця."},{"type":"related","target_id":"AUT-0534","reason":"Твердження покупця про конкурента потребує окремої перевірки перед використанням у відкритій угоді."},{"type":"related","target_id":"AUT-0009","reason":"Факт розмови й наступні дії підтверджують окремо від запрошення."}],"configurator_questions":[{"id":"post-decision-buyer-interview-evidence-segments","question":"Чи потрібні різні вибірки за продуктом, результатом або роллю покупця?","help_text":"Збережіть критерії, виключення й неучасть до порівняння висновків.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Збережіть критерії, виключення й неучасть до порівняння висновків."}]},{"id":"post-decision-buyer-interview-evidence-evidence","question":"Чи потрібне погоджене зберігання записів і узгодження тем між інтерв’юерами?","help_text":"Перевірте згоду, доступ, строки та відповідність висновку дозволеному свідченню.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Перевірте згоду, доступ, строки та відповідність висновку дозволеному свідченню."}]}]},{"schema_version":1,"id":"AUT-0617","slug":"conversion-outage-bidding-data-exclusion","title":"Захист рекламної оптимізації під час збою даних конверсій","summary":"Підтверджений збій вимірювання має погоджене виключення непридатних даних із автоматичного визначення ставок і окремий маршрут відновлення звітності.","problem":"Після збою тегу реклама сприймає зниклі конверсії як падіння попиту. Команда виключає лише дні збою без попередніх кліків або скасовує виключення після відновлення звіту.","outcome":"Зачеплені кампанії, пристрої й період кліків мають перевірений стан виключення; відновлення вимірювання та звітів не підміняє контроль даних для ставок.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","operations-manager"],"industries":["cross-industry"],"triggers":["Підтверджено несправність вимірювання або імпорту конверсій, що впливає на придатну автоматичну стратегію ставок."],"workflow_steps":["Зберегти доказ збою, його початок і кінець, конверсії, кампанії та пристрої; реальне падіння продажів не називати несправністю тегу.","Зіставити затримку конверсій із періодом попередніх кліків і часовим поясом акаунта; вибір днів конверсій сам по собі не визначає потрібне охоплення.","Перевірити підтримку виключення цільовою стратегією та погодити точні межі й допустимі витрати; не використовувати цей маршрут для постійного приховування слабких результатів.","Уповноважений оператор застосовує погоджене виключення та читає збережений стан; зберегти доказ охоплення без сліпого повтору.","Після окремого підтвердження ремонту вимірювання спостерігати роботу стратегії й витрати; коливання не оголошувати автоматично новим збоєм.","Погодити відновлення даних звітності лише за актуальними правилами платформи; не видаляти застосоване виключення лише тому, що звіт доповнено."],"requirements":["Є підтверджена несправність даних і доступні відомості про затримку конверсій.","Є придатна стратегія ставок, уповноважений оператор та погоджені межі витрат."],"limitations":["Виключення Google Ads застосовується до кліків і даних для ставок; воно не видаляє конверсії зі звітності.","Виключення не гарантує стабільних витрат або результату; підтримку, строки й відновлення даних перевіряють у чинній документації.","Ремонт сайту й відновлення первинних подій — окрема робота; не заявляємо автоматичного повернення втрачених конверсій.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Після збою тегу реклама сприймає зниклі конверсії як падіння попиту. Команда виключає лише дні збою без попередніх кліків або скасовує виключення після відновлення звіту."],"synonyms":["збій даних конверсій для ставок","виключення даних Smart Bidding","не видаляти виключення після відновлення звіту"],"search_queries":["як захистити автоматичні рекламні ставки коли зламалося відстеження конверсій з урахуванням попередніх кліків"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/google-ads/answer/10370710?hl=en","title":"Google Ads: виключення даних для автоматичних ставок","checked_at":"2026-10-10","supports":"Описано виключення кліків із непридатними конверсіями, охоплення кампаній і пристроїв та відмінність від звітності."},{"type":"vendor_documentation","url":"https://support.google.com/google-ads/answer/10276486?hl=en","title":"Google Ads: використання виключень під час збою","checked_at":"2026-10-10","supports":"Описано врахування затримки конверсій, межі використання й обмеження доповнення минулих даних. Результат не гарантується; виключення після застосування не слід скасовувати лише через ремонт даних."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"conversion-outage-bidding-data-exclusion-tracked","title":"Контроль із підтвердженням результату","description":"Підтверджений збій вимірювання має погоджене виключення непридатних даних із автоматичного визначення ставок і окремий маршрут відновлення звітності.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Імпорт конверсій не працював кілька днів. Маркетолог урахував попередні кліки й лише зачеплені пристрої; після ремонту відокремив доповнення звіту від чинного виключення для ставок.","implementation_methods":["Вести доказ збою й погоджене виключення з періодом кліків та фактичним станом.","Контролювати ремонт вимірювання, витрати й рішення щодо звітності як окремі результати."],"complexity":"medium","hours_min":22,"hours_max":44,"requirements":["Є підтверджена несправність даних і доступні відомості про затримку конверсій.","Є придатна стратегія ставок, уповноважений оператор та погоджені межі витрат."],"limitations":["Виключення Google Ads застосовується до кліків і даних для ставок; воно не видаляє конверсії зі звітності.","Виключення не гарантує стабільних витрат або результату; підтримку, строки й відновлення даних перевіряють у чинній документації.","Ремонт сайту й відновлення первинних подій — окрема робота; не заявляємо автоматичного повернення втрачених конверсій."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0544","reason":"Вимірювання воронки ремонтують окремо; успішний ремонт не скасовує виключення для ставок."},{"type":"related","target_id":"AUT-0555","reason":"Затримка й вікно конверсій допомагають пояснити охоплення, але не є самим виключенням."},{"type":"related","target_id":"AUT-0574","reason":"Корекція конкретного результату продажу не підміняє маршрут системного збою вимірювання."}],"configurator_questions":[{"id":"conversion-outage-bidding-data-exclusion-scope","question":"Чи збій охоплює кілька акаунтів, кампаній або груп пристроїв?","help_text":"Визначте точне охоплення, щоб не виключити справні дані.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Визначте точне охоплення, щоб не виключити справні дані."}]},{"id":"conversion-outage-bidding-data-exclusion-lag","question":"Чи конверсії мають різні затримки або потрібне доповнення звітів?","help_text":"Перевірте періоди кліків, невизначені дані та чинні правила відновлення.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Перевірте періоди кліків, невизначені дані та чинні правила відновлення."}]}]},{"schema_version":1,"id":"AUT-0618","slug":"short-promotion-conversion-rate-adjustment","title":"Погодження тимчасової рекламної оптимізації на період акції","summary":"Коротка акція з обґрунтованою нетиповою зміною частки покупок має обмежене коригування очікувань автоматичних ставок і перевірене завершення.","problem":"Під час короткої акції команда збільшує налаштування для всіх кампаній без підстав або лишає коригування після завершення. Пошуковий попит помилково приймають за зміну частки відвідувачів, які купують.","outcome":"Подія має погоджені підстави, строк, очікувану зміну частки конверсій і точне охоплення; фактичне завершення та відхилення пояснені окремо від прогнозу.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","owner"],"industries":["cross-industry"],"triggers":["Заплановано коротку акцію з обґрунтованим очікуванням суттєвої нетипової зміни частки конверсій."],"workflow_steps":["Зберегти редакцію акції, початок і кінець, умови та дані для очікуваної зміни частки конверсій; зростання запитів або бюджету не використовувати як її автоматичний доказ.","Перевірити, чи стандартна стратегія вже враховує звичайну сезонність і чи підтримує окреме коригування; тривалий сезон передати на інший план.","Погодити обмежену зміну, зачеплені кампанії й акаунти та контроль витрат; невпевнений прогноз не оголошувати гарантованим результатом.","Уповноважений оператор застосовує редакцію та перевіряє фактичні межі; нові або від’єднані акаунти звірити окремо від початкового списку.","Під час акції зіставити фактичні умови з планом і передати зміну строку чи скасування власнику; не продовжувати коригування без рішення.","Після завершення перевірити стан події й наступний період; не створювати протилежне коригування для завершення без підтримуваної підстави, а фактичний ефект не називати доведеним лише через збіг із продажами."],"requirements":["Є погоджена коротка акція й обґрунтування нетипової зміни частки конверсій.","Є підтримувана стратегія, оператор і власник строків, охоплення та допустимих витрат."],"limitations":["Google Ads описує короткі нетипові події; звичайну сезонність Smart Bidding враховує самостійно.","Це зміна очікуваної частки конверсій, а не розміру бюджету або гарантія додаткових покупок.","Приєднання нового акаунта не гарантує успадкування події; остаточні межі перевіряють у кожному придатному середовищі.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Під час короткої акції команда збільшує налаштування для всіх кампаній без підстав або лишає коригування після завершення. Пошуковий попит помилково приймають за зміну частки відвідувачів, які купують."],"synonyms":["коротка акція зміна частки конверсій","тимчасове коригування Smart Bidding","завершення сезонного рекламного коригування"],"search_queries":["як погодити тимчасове коригування рекламних ставок на коротку акцію і перевірити його завершення"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/google-ads/answer/10369906?hl=en","title":"Google Ads: тимчасові коригування сезонності","checked_at":"2026-10-10","supports":"Описано очікувану зміну частки конверсій для короткої нетипової події, завершення без протилежного коригування та правила охоплення кількох акаунтів. Це можливість продукту, не доказ приросту продажів."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"short-promotion-conversion-rate-adjustment-tracked","title":"Контроль із підтвердженням результату","description":"Коротка акція з обґрунтованою нетиповою зміною частки покупок має обмежене коригування очікувань автоматичних ставок і перевірене завершення.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Для короткої акції прогнозували нетипову зміну частки покупок. Власник погодив лише потрібні кампанії та строк; після завершення команда перевірила стан і не поширила подію автоматично на новий акаунт.","implementation_methods":["Вести подію з обґрунтуванням, часовими межами й редакцією погодженого коригування.","Зіставляти збережене охоплення та завершення з фактичними умовами акції й дозволеними витратами."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є погоджена коротка акція й обґрунтування нетипової зміни частки конверсій.","Є підтримувана стратегія, оператор і власник строків, охоплення та допустимих витрат."],"limitations":["Google Ads описує короткі нетипові події; звичайну сезонність Smart Bidding враховує самостійно.","Це зміна очікуваної частки конверсій, а не розміру бюджету або гарантія додаткових покупок.","Приєднання нового акаунта не гарантує успадкування події; остаточні межі перевіряють у кожному придатному середовищі."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0565","reason":"Пошуковий попит допомагає планувати акцію, але не доводить зміну частки конверсій."},{"type":"related","target_id":"AUT-0518","reason":"Темп витрат контролюють окремо від коригування очікуваної конверсії."},{"type":"related","target_id":"AUT-0244","reason":"Причинний ефект перевіряють належним експериментом, а не самим застосуванням коригування."}],"configurator_questions":[{"id":"short-promotion-conversion-rate-adjustment-accounts","question":"Чи акція охоплює кілька акаунтів або змінний склад кампаній?","help_text":"Звірте успадкування, приєднання й від’єднання з реальною участю в акції.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Звірте успадкування, приєднання й від’єднання з реальною участю в акції."}]},{"id":"short-promotion-conversion-rate-adjustment-changes","question":"Чи можливе скасування або зміна строку акції після запуску?","help_text":"Погодьте маршрут оновлення та перевірку фактичного завершення.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Погодьте маршрут оновлення та перевірку фактичного завершення."}]}]},{"schema_version":1,"id":"AUT-0619","slug":"joint-target-company-selection","title":"Погодження цільових компаній для спільного залучення","summary":"Продажі й маркетинг працюють із погодженою вибіркою компаній, поясненими критеріями та власниками залучення.","problem":"Маркетинг готує кампанію для одного набору компаній, а продавці обробляють інший. Динамічний список змінюється без рішення, а схожа назва додає чужу організацію.","outcome":"Програма залучення має погоджену редакцію цільових компаній, пояснені включення й виключення та підтверджене передавання власникам роботи.","category":"sales-crm","subcategory":"sales-operations","roles":["sales-manager","marketer"],"industries":["cross-industry"],"triggers":["Команда планує спільне залучення вибраних компаній або суттєво змінює критерії чинної програми."],"workflow_steps":["Зберегти мету залучення, період, потрібні ознаки компаній, доступні ресурси й винятки; не переносити без рішення весь список контактів CRM.","Зіставити компанії за перевіреними ключами та актуальними джерелами; однойменні організації й групу юридичних осіб передати на уточнення.","Побудувати пояснену вибірку та позначити, чи вона статична або змінюється за правилами; відсутні ознаки не підміняти відповідністю.","Погодити конкретну редакцію продажами й маркетингом, власників залучення та зміни щодо попереднього набору; пріоритет компанії не означає дозвіл написати кожному контакту.","Передати погоджений список у дозволені робочі маршрути й звірити фактичний склад після потрібної затримки; назва списку не доводить його актуальності.","Наступні входи й виходи компаній зіставляти з чинними критеріями та активною роботою; суттєву зміну повертати на рішення без автоматичного закриття угод."],"requirements":["Є погоджена мета, критерії й власники програми продажів та маркетингу.","Є дозволені джерела компаній, стабільні ключі та спосіб перевірити фактичний склад списків."],"limitations":["Список компаній не є поіменним списком придатних одержувачів реклами чи доказом дозволу на контакт.","Marketo описує статичні й динамічні списки з різними передумовами та затримками; це не заява про готову однакову функцію PlanFix.","Вибір компанії не доводить імовірності продажу; права, джерела й обсяг ручної перевірки уточнюють на аудиті.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Маркетинг готує кампанію для одного набору компаній, а продавці обробляють інший. Динамічний список змінюється без рішення, а схожа назва додає чужу організацію."],"synonyms":["цільові компанії спільного залучення","погоджений список акаунтів для продажів","зміна динамічного списку компаній"],"search_queries":["як узгодити список цільових компаній між продажами і маркетингом без різних вибірок"],"sources":[{"type":"vendor_documentation","url":"https://experienceleague.adobe.com/en/docs/marketo/using/product-docs/target-account-management/target/account-lists","title":"Adobe Marketo: списки цільових компаній","checked_at":"2026-10-12","supports":"Описано статичні та динамічні списки компаній, правила CRM-вибірки та затримки оновлення. Погодження ресурсів і змін — редакційна модель."},{"type":"vendor_documentation","url":"https://experienceleague.adobe.com/en/docs/marketo/using/product-docs/target-account-management/setup/getting-started-with-tam","title":"Adobe Marketo: підготовка цільових компаній","checked_at":"2026-10-12","supports":"Описано імпорт, пошук у CRM та інших джерелах і передумови доступу. Джерело не доводить придатності конкретної компанії чи контактного дозволу."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"joint-target-company-selection-tracked","title":"Контроль із підтвердженням результату","description":"Продажі й маркетинг працюють із погодженою вибіркою компаній, поясненими критеріями та власниками залучення.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Продажі й маркетинг звірили різні списки компаній і погодили одну вибірку. Після зміни динамічного правила власник перевірив нові входи та зберіг рішення щодо вже відкритих угод.","implementation_methods":["Вести редакцію критеріїв, компаній і відповідальних як спільний план залучення.","Зіставляти погоджену вибірку з фактичними списками й окремо розглядати зміни активної роботи."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є погоджена мета, критерії й власники програми продажів та маркетингу.","Є дозволені джерела компаній, стабільні ключі та спосіб перевірити фактичний склад списків."],"limitations":["Список компаній не є поіменним списком придатних одержувачів реклами чи доказом дозволу на контакт.","Marketo описує статичні й динамічні списки з різними передумовами та затримками; це не заява про готову однакову функцію PlanFix.","Вибір компанії не доводить імовірності продажу; права, джерела й обсяг ручної перевірки уточнюють на аудиті."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0521","reason":"Додаткові відомості компанії перевіряють окремо від рішення включити її у програму."},{"type":"related","target_id":"AUT-0513","reason":"Пріоритет конкретного ліда не визначає весь стратегічний список компаній."},{"type":"related","target_id":"AUT-0541","reason":"Розвиток чинного ключового клієнта має свій план після вибору належного контексту."}],"configurator_questions":[{"id":"joint-target-company-selection-sources","question":"Чи компанії надходять із кількох джерел або мають складні юридичні групи?","help_text":"Перевірте ключі, неоднозначні збіги й підтверджене охоплення.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Перевірте ключі, неоднозначні збіги й підтверджене охоплення."}]},{"id":"joint-target-company-selection-dynamic","question":"Чи склад змінюється автоматично за правилами CRM?","help_text":"Погодьте суттєві входи й виходи, затримку та вплив на активну роботу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Погодьте суттєві входи й виходи, затримку та вплив на активну роботу."}]}]},{"schema_version":1,"id":"AUT-0620","slug":"closed-campaign-intake-retirement","title":"Завершення збору заявок за закритою кампанією","summary":"Закрита кампанія припиняє придатні маршрути нових заявок і запуску серій, а вже прийняті звернення зберігають належну обробку.","problem":"Акція завершилась, але стара сторінка чи активний сценарій продовжує приймати заявки й обіцяти участь. Команда зняла одну сторінку, проте інший маршрут залишився активним.","outcome":"Застарілі маршрути мають перевірений результат завершення та погоджену відповідь пізнім відвідувачам; чинні спільні форми й уже прийняті заявки обробляються за окремими рішеннями.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","operations-manager"],"industries":["cross-industry"],"triggers":["Власник підтвердив закриття або скасування кампанії та погодив кінцеву межу приймання заявок."],"workflow_steps":["Зберегти кампанію, кінцеву межу з часовим поясом, усі відомі сторінки, форми, тригерні та періодичні сценарії; спільне використання ресурсів перевірити окремо.","Погодити поведінку після межі: повідомлення про завершення, інший придатний маршрут або припинення запуску; вже прийняту заявку не видаляти через закриття.","Налаштувати підтримуване завершення лише потрібних ресурсів і зберегти їхні ключі; перевірити потрібні права й обмеження запланованої зміни.","Перед закриттям перевірити, що перенесення ресурсу чи зміна програми не скасували розклад; спільний ресурс не відключати для чинної кампанії.","Після межі звірити фактичну доступність відомих шляхів і стан запуску серій; приховування з пошуку не означає припинення приймання.","Позначити пізні звернення й винятки для рішення власника, зберегти раніше прийняті заявки та докази завершення; невідомі сторонні копії не називати перевіреними."],"requirements":["Є погоджена межа приймання, перелік ресурсів і власники спільних форм та сценаріїв.","Є дозволений маршрут завершення й можливість перевірити сторінки та фактичний стан кампанії."],"limitations":["Marketo описує завершення місцевих сторінок і сценаріїв; це не гарантія вимкнення всіх сторонніх або вбудованих форм.","Перенесення ресурсу до іншої програми може прибрати його заплановане завершення; готовий розклад треба звіряти після змін.","Виправлення зовнішніх інтеграцій і невідомих копій оцінюють окремо; завершення не скасовує підтверджених зобов’язань перед учасниками.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Акція завершилась, але стара сторінка чи активний сценарій продовжує приймати заявки й обіцяти участь. Команда зняла одну сторінку, проте інший маршрут залишився активним."],"synonyms":["завершення збору заявок кампанії","стара форма після закриття акції","перевірка кінцевої межі кампанії"],"search_queries":["як припинити заявки і запуск розсилок після завершення кампанії не вимкнувши спільні форми"],"sources":[{"type":"vendor_documentation","url":"https://experienceleague.adobe.com/en/docs/marketo/using/product-docs/core-marketo-concepts/programs/working-with-programs/local-asset-expiration","title":"Adobe Marketo: завершення ресурсів програми","checked_at":"2026-10-12","supports":"Описано заплановане зняття сторінок, деактивацію тригерних і періодичних кампаній, права та втрату розкладу при перенесенні. Облік шляхів і пізніх заявок — редакційна модель."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"closed-campaign-intake-retirement-tracked","title":"Контроль із підтвердженням результату","description":"Закрита кампанія припиняє придатні маршрути нових заявок і запуску серій, а вже прийняті звернення зберігають належну обробку.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Акція закрилась, але спільна форма працювала й для іншої послуги. Команда завершила лише потрібну сторінку та запуск акційної серії, звірила прямий шлях і передала пізню заявку власнику.","implementation_methods":["Вести перелік ресурсів, погоджену межу та результат завершення кожного належного маршруту.","Зіставляти розклад і фактичний стан, зберігаючи вже прийняті заявки та чинні спільні використання."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є погоджена межа приймання, перелік ресурсів і власники спільних форм та сценаріїв.","Є дозволений маршрут завершення й можливість перевірити сторінки та фактичний стан кампанії."],"limitations":["Marketo описує завершення місцевих сторінок і сценаріїв; це не гарантія вимкнення всіх сторонніх або вбудованих форм.","Перенесення ресурсу до іншої програми може прибрати його заплановане завершення; готовий розклад треба звіряти після змін.","Виправлення зовнішніх інтеграцій і невідомих копій оцінюють окремо; завершення не скасовує підтверджених зобов’язань перед учасниками."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0020","reason":"Заявки, прийняті до межі, зберігають підтверджену обробку."},{"type":"related","target_id":"AUT-0605","reason":"Пошукове приховування застарілої пропозиції не завершує прямі маршрути приймання."},{"type":"related","target_id":"AUT-0019","reason":"Закриття кампанії має пояснений вплив на подальші кроки серій."}],"configurator_questions":[{"id":"closed-campaign-intake-retirement-shared","question":"Чи ресурси використовують кілька програм або сторонніх форм?","help_text":"Зіставте всі відомі прив’язки й дозволений спосіб завершення потрібної частини.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Зіставте всі відомі прив’язки й дозволений спосіб завершення потрібної частини."}]},{"id":"closed-campaign-intake-retirement-late","question":"Чи потрібні різні рішення для пізніх і вже прийнятих заявок?","help_text":"Погодьте межу, повідомлення та чинні зобов’язання перед учасниками.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте межу, повідомлення та чинні зобов’язання перед учасниками."}]}]},{"schema_version":1,"id":"AUT-0621","slug":"provider-suspension-sending-recovery","title":"Відновлення надсилання після блокування поштовим сервісом","summary":"Обмеження поштового акаунта має перевірену причину, належні виправлення й підтверджений результат дозволеного відновлення.","problem":"Сервіс заблокував надсилання, а команда повторно запускає кампанії або переносить заборонену базу до іншого акаунта. Очищення частини адрес помилково вважають зняттям обмеження провайдера.","outcome":"Причина й охоплення блокування пояснені, вимоги виконані, а право надсилання підтверджене або лишається відкритим; відписки й скарги не скидаються під час відновлення.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","owner"],"industries":["cross-industry"],"triggers":["Провайдер повідомив про блокування акаунта чи надсилання маркетингових кампаній."],"workflow_steps":["Зберегти точне повідомлення, акаунт, час, зачеплений маршрут і історію попередніх обмежень; локальну помилку або адресну заборону не називати блокуванням усього сервісу.","Визначити застосовний маршрут за реальною причиною: якість кампаній, реєстрація, компрометація або інша вимога; одну процедуру не застосовувати до всіх причин.","Погодити виправлення за чинними вимогами акаунта й призначити власників; перевірити джерело контактів, дозволи та потрібну технічну автентифікацію без зняття скарг.","Уповноважений власник виконує дозволену повторну перевірку або звернення; непідтримуване відновлення не обходити новим акаунтом чи повторними надсиланнями.","Прочитати фактичний результат і охоплення права надсилання; подання або завершення локальних задач не прирівнювати до знятого блокування.","Погодити належний наступний режим і спостерігати доступні результати; невизначену можливість надсилання чи повторне обмеження повернути власнику без автоматичного масового тесту."],"requirements":["Є доступ до реального повідомлення провайдера й історії обмежень цільового акаунта.","Є уповноважений власник, докази виправлення та дозволений маршрут перевірки стану."],"limitations":["Правила залежать від причини та історії; Brevo не гарантує відновлення після повторного або іншого неприпустимого порушення.","Поліпшення репутації чи зняття окремої адресної заборони не доводить зняття обмеження акаунта.","Не обіцяємо гарантоване відновлення, не надсилаємо реальних тестів без окремого дозволу й не оцінюємо роботу зовнішньої підтримки як керовану автоматизацію.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Сервіс заблокував надсилання, а команда повторно запускає кампанії або переносить заборонену базу до іншого акаунта. Очищення частини адрес помилково вважають зняттям обмеження провайдера."],"synonyms":["поштовий сервіс заблокував акаунт","повторна перевірка надсилання кампаній","не обходити блокування новим акаунтом"],"search_queries":["як перевірити відновлення права надсилати маркетингові листи після блокування акаунта провайдером"],"sources":[{"type":"vendor_documentation","url":"https://help.brevo.com/hc/en-us/articles/360017299259-Why-have-my-account-or-email-campaigns-been-suspended","title":"Brevo: причини блокування й різні маршрути відновлення","checked_at":"2026-10-12","supports":"Описано різні причини, вимоги цільового повідомлення та обмеження повторного відновлення. Компрометація має окремий маршрут."},{"type":"vendor_documentation","url":"https://help.brevo.com/hc/en-us/articles/209408165-Reactivate-your-email-campaigns-after-a-suspension","title":"Brevo: відновлення після негативних результатів кампаній","checked_at":"2026-10-12","supports":"Описано перевірку вимог у центрі доставлюваності, належні контакти й практики надсилання. Виконання рекомендацій не гарантує прийняття або доброї доставки."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"provider-suspension-sending-recovery-tracked","title":"Контроль із підтвердженням результату","description":"Обмеження поштового акаунта має перевірену причину, належні виправлення й підтверджений результат дозволеного відновлення.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Після блокування за результатами кампанії власник перевірив вимоги акаунта й виправив джерело аудиторії. Команда дочекалась підтвердженого стану, зберегла відписки та погодила наступний режим без масового тесту.","implementation_methods":["Вести один випадок обмеження з причиною, вимогами й фактичним результатом провайдера.","Погоджувати виправлення та відновлення лише належним маршрутом із перевіркою охоплення права надсилання."],"complexity":"medium","hours_min":22,"hours_max":44,"requirements":["Є доступ до реального повідомлення провайдера й історії обмежень цільового акаунта.","Є уповноважений власник, докази виправлення та дозволений маршрут перевірки стану."],"limitations":["Правила залежать від причини та історії; Brevo не гарантує відновлення після повторного або іншого неприпустимого порушення.","Поліпшення репутації чи зняття окремої адресної заборони не доводить зняття обмеження акаунта.","Не обіцяємо гарантоване відновлення, не надсилаємо реальних тестів без окремого дозволу й не оцінюємо роботу зовнішньої підтримки як керовану автоматизацію."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0529","reason":"Спостереження репутації допомагає аналізувати причину, але не знімає обмеження сервісу."},{"type":"related","target_id":"AUT-0556","reason":"Адресні заборони зберігають власні правила й не скидаються під час відновлення акаунта."},{"type":"related","target_id":"AUT-0087","reason":"Підтверджену компрометацію передають на належний маршрут безпеки."}],"configurator_questions":[{"id":"provider-suspension-sending-recovery-routes","question":"Чи обмеження охоплює кілька акаунтів або різні типи надсилання?","help_text":"Звірте причини й дозволені маршрути кожного обмеження окремо.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Звірте причини й дозволені маршрути кожного обмеження окремо."}]},{"id":"provider-suspension-sending-recovery-history","question":"Чи потрібен окремий розгляд повторної зупинки або суперечливого рішення?","help_text":"Збережіть попередні вимоги, докази та допустимість звернення без гарантованого відновлення.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Збережіть попередні вимоги, докази та допустимість звернення без гарантованого відновлення."}]}]},{"schema_version":1,"id":"AUT-0622","slug":"marketing-claim-evidence-approval","title":"Погодження доказів рекламних тверджень","summary":"Числові результати й обіцянки в рекламі мають перевірені підстави, межі застосування та погоджену редакцію.","problem":"У рекламу потрапляє результат одного клієнта як обіцянка для всіх. Команда не може знайти джерело цифри або пояснити умови, за яких отримано результат.","outcome":"Власник погоджує конкретне твердження з доказом і належними умовами або повертає його на виправлення; непідтверджена обіцянка не отримує внутрішнього дозволу.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","owner"],"industries":["cross-industry"],"triggers":["Новий матеріал містить вимірюваний результат, порівняння або обіцянку, для якої потрібні підстави."],"workflow_steps":["Виділити точне твердження, редакцію матеріалу, пропозицію та контекст використання; згоду на зображення не вважати доказом цифри.","Пов’язати цифру з первинним записом, періодом, способом вимірювання й умовами; відсутній доказ залишити відкритим.","Перевірити охоплення доказу: окремий випадок, вибірка чи погоджений результат; не переносити одиничний успіх на всіх покупців.","Власник предметної області погоджує формулювання, істотні умови й потрібні пояснення або відхиляє обіцянку; автоматичний текст не отримує схвалення самостійно.","Передати дозволену редакцію в підготовку матеріалу та звірити фактичний текст і видимість пояснень; схвалення платформою не доводить достовірності.","Зміни доказу, продукту чи умов повертають пов’язані твердження на перегляд; зберегти рішення щодо виправлення чинних використань."],"requirements":["Є доступні первинні підстави тверджень і власник, який може перевірити їхній зміст.","Є облік редакцій матеріалів і дозволений маршрут погодження та виправлення."],"limitations":["Google описує заборону недостовірних і малоймовірних обіцянок; внутрішнє погодження не гарантує прийняття реклами.","Це контроль доказів змісту, а не прав на матеріал, юридична експертиза або лікувальні чи інвестиційні рекомендації.","Перевірка доказів потребує уповноваженої людини; автоматизація не вигадує відсутніх результатів.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["У рекламу потрапляє результат одного клієнта як обіцянка для всіх. Команда не може знайти джерело цифри або пояснити умови, за яких отримано результат."],"synonyms":["доказ рекламного твердження","підстави обіцянки результату","перевірка цифр рекламного матеріалу"],"search_queries":["як погодити докази цифр і обіцянок у рекламі перед публікацією"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/adspolicy/answer/15936857?hl=en","title":"Google Ads: недостовірні твердження","checked_at":"2026-10-12","supports":"Правила забороняють недостовірні та малоймовірні обіцянки як очікуваний результат. Облік первинних доказів і погодження редакцій — редакційна модель."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"marketing-claim-evidence-approval-tracked","title":"Контроль із підтвердженням результату","description":"Числові результати й обіцянки в рекламі мають перевірені підстави, межі застосування та погоджену редакцію.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Матеріал обіцяв усім покупцям результат одного проєкту. Власник знайшов вихідний розрахунок, звузив твердження до конкретного випадку й погодив текст із видимими умовами.","implementation_methods":["Пов’язувати кожне суттєве твердження з доказом, умовами й власником перевірки.","Передавати лише погоджену редакцію та повертати зачеплені матеріали на перегляд після зміни підстав."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є доступні первинні підстави тверджень і власник, який може перевірити їхній зміст.","Є облік редакцій матеріалів і дозволений маршрут погодження та виправлення."],"limitations":["Google описує заборону недостовірних і малоймовірних обіцянок; внутрішнє погодження не гарантує прийняття реклами.","Це контроль доказів змісту, а не прав на матеріал, юридична експертиза або лікувальні чи інвестиційні рекомендації.","Перевірка доказів потребує уповноваженої людини; автоматизація не вигадує відсутніх результатів."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0255","reason":"Дозвіл використовувати матеріал не підтверджує достовірності його твердження."},{"type":"related","target_id":"AUT-0593","reason":"Сумісність рекламних фрагментів перевіряють після погодження їхнього змісту."},{"type":"related","target_id":"AUT-0106","reason":"Фактичне відхилення платформою має окремий маршрут опрацювання."}],"configurator_questions":[{"id":"marketing-claim-evidence-approval-evidence","question":"Чи докази надходять із кількох систем або мають різні методи вимірювання?","help_text":"Звірте періоди, вихідні записи та межі порівняння.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Звірте періоди, вихідні записи та межі порівняння."}]},{"id":"marketing-claim-evidence-approval-uses","question":"Чи твердження повторюється в кількох чинних матеріалах?","help_text":"Збережіть прив’язки й рішення щодо кожної зачепленої редакції.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Збережіть прив’язки й рішення щодо кожної зачепленої редакції."}]}]},{"schema_version":1,"id":"AUT-0623","slug":"declining-creative-renewal-review","title":"Перегляд рекламних матеріалів після втрати ефективності","summary":"Стійке погіршення результатів матеріалу запускає пояснений перегляд і погоджене завдання на оновлення.","problem":"Команда місяцями показує той самий матеріал або замінює його через випадковий спад. Падіння через зламане вимірювання помилково називають втомою аудиторії.","outcome":"Власник має перевірений сигнал, пояснену потребу оновлення або інше рішення, а новий матеріал проходить погодження й підтверджене передавання у потрібну кампанію.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","operations-manager"],"industries":["cross-industry"],"triggers":["Доступні результати рекламного матеріалу стійко погіршуються за погодженим правилом спостереження."],"workflow_steps":["Пов’язати матеріал із фактичними показами, періодом і кампанією; визначити правило перегляду та мінімальну придатність даних.","Зіставити тренд з історією, затримками результатів і змінами аудиторії, ставки, бюджету та вимірювання; разовий спад не доводить втому.","Маркетолог визначає підставу рішення: оновити матеріал, усунути іншу причину або продовжити спостереження; сумнів не перетворювати на автоматичну заміну.","Для погодженого оновлення сформувати завдання з гіпотезою зміни, чинними умовами пропозиції, власником і строком; пов’язати нову редакцію з попередньою.","Уповноважена команда погоджує матеріал і передавання в належне місце; прочитати фактичний набір реклами та залишити невиконане передавання відкритим.","Після придатного періоду звірити доступні результати й рішення власника; поліпшення без контрольного експерименту не оголошувати доведеним причинним ефектом."],"requirements":["Є результати на рівні матеріалів, стабільні ключі й відома історія змін кампанії.","Є погоджене правило перегляду, власник рішення та маршрут підготовки нового матеріалу."],"limitations":["TikTok рекомендує регулярний перегляд і оновлення за стійкого спаду; конкретні пороги та пояснення причин треба погодити.","Оновлення матеріалу не замінює контрольного експерименту й не гарантує зниження вартості заявки.","Виробництво відео чи дизайну, рекламні витрати та можливості цільового кабінету оцінюють окремо.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Команда місяцями показує той самий матеріал або замінює його через випадковий спад. Падіння через зламане вимірювання помилково називають втомою аудиторії."],"synonyms":["оновлення реклами після спаду результатів","перегляд втоми рекламного матеріалу","завдання на заміну рекламного креативу"],"search_queries":["як запускати оновлення рекламних матеріалів за стійкого спаду результатів а не випадкового дня"],"sources":[{"type":"vendor_documentation","url":"https://ads.tiktok.com/resources/help/article/creative-best-practices?lang=en","title":"TikTok: перегляд і оновлення рекламних матеріалів","checked_at":"2026-10-12","supports":"Рекомендовано регулярно перевіряти результати й оновлювати матеріали за стійкого спаду, зберігати їхню бібліотеку. Джерело не доводить причини спаду або гарантованого ефекту."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"declining-creative-renewal-review-tracked","title":"Контроль із підтвердженням результату","description":"Стійке погіршення результатів матеріалу запускає пояснений перегляд і погоджене завдання на оновлення.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Після кількох придатних періодів команда перевірила спад і справність вимірювання. Маркетолог погодив нове завдання на матеріал, а власник звірив його фактичне передавання без обіцянки гарантованого зростання.","implementation_methods":["Спостерігати результати конкретних матеріалів і передавати пояснений сигнал власнику.","Пов’язувати рішення про оновлення, завдання, редакцію та фактичне передавання в кампанію."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є результати на рівні матеріалів, стабільні ключі й відома історія змін кампанії.","Є погоджене правило перегляду, власник рішення та маршрут підготовки нового матеріалу."],"limitations":["TikTok рекомендує регулярний перегляд і оновлення за стійкого спаду; конкретні пороги та пояснення причин треба погодити.","Оновлення матеріалу не замінює контрольного експерименту й не гарантує зниження вартості заявки.","Виробництво відео чи дизайну, рекламні витрати та можливості цільового кабінету оцінюють окремо."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0244","reason":"Доведення ефекту конкретної зміни потребує окремого експерименту."},{"type":"related","target_id":"AUT-0103","reason":"Погоджене завдання на новий матеріал передають у план підготовки."},{"type":"related","target_id":"AUT-0518","reason":"Рішення щодо темпу бюджету не замінює перегляду матеріалу."}],"configurator_questions":[{"id":"declining-creative-renewal-review-history","question":"Чи дані й історія змін надходять із кількох рекламних кабінетів?","help_text":"Зіставте ключі матеріалів, періоди й доступність історії.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Зіставте ключі матеріалів, періоди й доступність історії."}]},{"id":"declining-creative-renewal-review-handoff","question":"Чи оновлення потребує кількох команд або спільних матеріалів?","help_text":"Погодьте власників, зачеплені кампанії й перевірку передавання.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Погодьте власників, зачеплені кампанії й перевірку передавання."}]}]},{"schema_version":1,"id":"AUT-0624","slug":"buyer-security-questionnaire-response","title":"Погодження відповідей на анкету безпеки покупця","summary":"Анкета покупця отримує відповіді з придатних доказів, перевірку фахівцями й погоджений пакет для конкретної угоди.","problem":"Продавець копіює відповіді іншого продукту або віддає покупцю неперевірені припущення. Питання без підтвердження губляться між фахівцями й затримують угоду.","outcome":"Кожне питання має придатну погоджену відповідь або відкритий виняток; покупцю передають конкретну перевірену редакцію без вигаданих гарантій і сертифікатів.","category":"sales-crm","subcategory":"sales-operations","roles":["sales-manager","operations-manager"],"industries":["cross-industry"],"triggers":["Покупець надіслав анкету безпеки для перевірки постачальника в межах угоди."],"workflow_steps":["Зберегти угоду, редакцію анкети, продукт, спосіб розміщення, потрібний строк і межі розкриття документів.","Зіставити питання з чинними погодженими відповідями й доказами належного продукту та контексту; схожість тексту не доводить застосовності.","Невідомі, суперечливі або застарілі відповіді передати предметним фахівцям із власником і строком; відсутній доказ не замінювати позитивною відповіддю.","Фахівці перевіряють зміст, винятки та дозволений обсяг розкриття; автоматична чернетка лишається непогодженою до рішення.","Звірити повноту, остаточну редакцію й права на вкладення; уповноважений власник погоджує передавання покупцю та зберігає фактичний результат.","Нові відповіді додавати в бібліотеку лише після окремого погодження придатності; завершення анкети не означає сертифікації чи автоматичного прийняття покупцем."],"requirements":["Є анкета, предметні фахівці й чинні контрольовані записи про власний продукт.","Є правила розкриття, погодження та дозволений маршрут передавання покупцю."],"limitations":["Vanta описує бібліотеку відповідей, перевірку та обмеження контексту; конкретна ліцензія й можливості середовища потребують аудиту.","Автоматизація не проводить аудит постачальника й не доводить технічну придатність продукту через практичний тест.","Бібліотека не покриває невідомих питань; відповіді, сертифікати й факти власного продукту не можна вигадувати.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Продавець копіює відповіді іншого продукту або віддає покупцю неперевірені припущення. Питання без підтвердження губляться між фахівцями й затримують угоду."],"synonyms":["анкета безпеки для угоди","відповіді покупцю про захист даних","погоджена бібліотека відповідей продажів"],"search_queries":["як погодити відповіді на анкету безпеки покупця з доказами і фахівцями перед передаванням"],"sources":[{"type":"vendor_documentation","url":"https://help.vanta.com/en/articles/11345464-getting-started-with-questionnaire-automation","title":"Vanta: підготовка й погодження відповідей на анкети","checked_at":"2026-10-12","supports":"Описано бібліотеку ресурсів і відповідей, перевірку всіх відповідей, підтримання актуальності й межу покриття базою."},{"type":"vendor_documentation","url":"https://help.vanta.com/en/articles/11345454-using-tags-for-answering-security-questionnaires","title":"Vanta: контекст відповідей за продуктом і регіоном","checked_at":"2026-10-12","supports":"Описано відбір джерел і відповідей за тегами анкети; застосовність непозначених матеріалів потребує явного рішення."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"buyer-security-questionnaire-response-tracked","title":"Контроль із підтвердженням результату","description":"Анкета покупця отримує відповіді з придатних доказів, перевірку фахівцями й погоджений пакет для конкретної угоди.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Покупець запитав про захист окремого продукту. Продавець передав невідомі питання фахівцю, звірив докази й погодив пакет без копіювання сертифікатів іншого рішення.","implementation_methods":["Пов’язувати питання покупця з придатними відповідями, доказами й власниками уточнення.","Зберігати погоджену редакцію для угоди, а нові відповіді окремо перевіряти для повторного використання."],"complexity":"medium","hours_min":22,"hours_max":44,"requirements":["Є анкета, предметні фахівці й чинні контрольовані записи про власний продукт.","Є правила розкриття, погодження та дозволений маршрут передавання покупцю."],"limitations":["Vanta описує бібліотеку відповідей, перевірку та обмеження контексту; конкретна ліцензія й можливості середовища потребують аудиту.","Автоматизація не проводить аудит постачальника й не доводить технічну придатність продукту через практичний тест.","Бібліотека не покриває невідомих питань; відповіді, сертифікати й факти власного продукту не можна вигадувати."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0577","reason":"Практична перевірка сценаріїв покупця має окремі результати й критерії."},{"type":"related","target_id":"AUT-0465","reason":"Аудит чужого постачальника не замінює доказів відповідей про власний продукт."}],"configurator_questions":[{"id":"buyer-security-questionnaire-response-scope","question":"Чи відповіді різняться між продуктами або способами розміщення?","help_text":"Перевірте контекст кожного доказу та заборонені перенесення.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Перевірте контекст кожного доказу та заборонені перенесення."}]},{"id":"buyer-security-questionnaire-response-experts","question":"Чи анкета потребує кількох фахівців і обмежених документів?","help_text":"Погодьте строки, винятки та дозволений пакет розкриття.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте строки, винятки та дозволений пакет розкриття."}]}]},{"schema_version":1,"id":"AUT-0625","slug":"similar-won-deal-precedent-selection","title":"Добір досвіду виграних угод для поточного продажу","summary":"Менеджер отримує пояснений добір схожих виграних угод і перевіряє, який досвід придатний для поточного покупця.","problem":"Команда повторно шукає, як продавала схоже рішення. Випадкову успішну угоду копіюють без перевірки потреб, складу продукту та відмінностей покупця.","outcome":"Поточна угода має перевірені внутрішні приклади, пояснену застосовність і погоджену наступну дію; схожість не стає обіцянкою такого самого результату.","category":"sales-crm","subcategory":"sales-operations","roles":["sales-manager","operations-manager"],"industries":["cross-industry"],"triggers":["Менеджеру потрібен досвід попередніх продажів для конкретної активної угоди."],"workflow_steps":["Зберегти поточну угоду, продукт, контекст покупця й питання менеджера; визначити доступну історію та правила використання чужих матеріалів.","Добрати доступні виграні угоди й зберегти підстави схожості, дату та охоплення вибірки; схожі записи не зливати як дублікати.","Менеджер перевіряє фактичний склад продажу, особливості потреб і важливі відмінності; невідомі подробиці передати власнику попередньої угоди.","Позначити придатні уроки, непридатні умови та обмеження; один виграш не доводить універсального способу продажу чи ймовірності перемоги.","Погодити внутрішню рекомендацію та наступну дію для поточної угоди; зовнішнє розкриття клієнтських даних або референсну розмову погоджувати окремо.","Зберегти використаний добір і рішення, а зміни продукту чи матеріалів повертати на перегляд; завершення пошуку не дорівнює виконанню дії."],"requirements":["Є доступна історія виграних угод, склад продуктів і стабільні ключі записів.","Є власник перевірки, правила доступу та спосіб зберігати підстави добору."],"limitations":["Salesforce описує добір схожих виграних угод із власними часовими й ліцензійними обмеженнями; його правила не переносять автоматично в PlanFix.","Схожість не є доказом дубля, прогнозом виграшу або дозволом розкрити дані попереднього покупця.","Неповна історія й відбір лише виграшів обмежують висновки; підготовку відсутніх даних оцінюють окремо.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Команда повторно шукає, як продавала схоже рішення. Випадкову успішну угоду копіюють без перевірки потреб, складу продукту та відмінностей покупця."],"synonyms":["досвід схожих виграних продажів","внутрішні приклади для активної угоди","перевірка застосовності попереднього продажу"],"search_queries":["як знайти придатний досвід схожих виграних угод для поточного покупця"],"sources":[{"type":"vendor_documentation","url":"https://help.salesforce.com/s/articleView?id=ai.copilot_actions_ref_find_similar_opportunities.htm&language=en_US&type=5","title":"Salesforce: добір схожих виграних угод","checked_at":"2026-10-12","supports":"Описано пояснення схожості, читання лише доступних записів, часові та інші обмеження добору. Перевірка уроків і наступної дії — редакційна модель."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"similar-won-deal-precedent-selection-tracked","title":"Контроль із підтвердженням результату","description":"Менеджер отримує пояснений добір схожих виграних угод і перевіряє, який досвід придатний для поточного покупця.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Менеджер знайшов схожий виграний продаж, але попередній покупець мав іншу конфігурацію. Команда зберегла придатні запитання й відкинула непридатну умову без копіювання чужого договору.","implementation_methods":["Добирати доступні попередні виграші з поясненням схожості й межами вибірки.","Перевіряти застосовність досвіду та зберігати погоджену дію в поточній угоді."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є доступна історія виграних угод, склад продуктів і стабільні ключі записів.","Є власник перевірки, правила доступу та спосіб зберігати підстави добору."],"limitations":["Salesforce описує добір схожих виграних угод із власними часовими й ліцензійними обмеженнями; його правила не переносять автоматично в PlanFix.","Схожість не є доказом дубля, прогнозом виграшу або дозволом розкрити дані попереднього покупця.","Неповна історія й відбір лише виграшів обмежують висновки; підготовку відсутніх даних оцінюють окремо."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0513","reason":"Оцінка пріоритету ліда не замінює поясненого добору внутрішніх прикладів."},{"type":"related","target_id":"AUT-0590","reason":"Розмова покупця з попереднім клієнтом потребує окремого дозволу."},{"type":"related","target_id":"AUT-0616","reason":"Інтерв’ю щодо причин рішення доповнює досвід, але не є добором для конкретної угоди."}],"configurator_questions":[{"id":"similar-won-deal-precedent-selection-history","question":"Чи історія має кілька систем або неповний склад проданих продуктів?","help_text":"Зіставте ключі, редакції та фактичну придатність матеріалів.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Зіставте ключі, редакції та фактичну придатність матеріалів."}]},{"id":"similar-won-deal-precedent-selection-access","question":"Чи потрібні окремі права й погодження власників минулих угод?","help_text":"Погодьте доступ, дозволені уроки й межі розкриття даних.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Погодьте доступ, дозволені уроки й межі розкриття даних."}]}]},{"schema_version":1,"id":"AUT-0626","slug":"advertising-auction-competition-review","title":"Перегляд змін конкуренції в рекламних аукціонах","summary":"Маркетолог отримує пояснену зміну конкуренції в доступних аукціонах і погоджує доречну дію без автоматичного підвищення ставок.","problem":"Команда пояснює втрату показів появою конкурента без зіставного звіту. Частку в спільних аукціонах помилково видають за частку ринку або весь бюджет іншого рекламодавця.","outcome":"Зміна охоплення й перекриття має перевірену область порівняння, пояснені обмеження та рішення власника: спостерігати, дослідити або погодити окрему зміну кампанії.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","owner"],"industries":["cross-industry"],"triggers":["Погоджений перегляд виявив суттєву зміну конкурентних показників у доступному звіті рекламних аукціонів."],"workflow_steps":["Зберегти акаунт, кампанії, тип реклами, період, пристрої та доступне охоплення звіту; відсутні дані не називати відсутністю конкуренції.","Отримати зіставні зрізи й відокремити показники спільних аукціонів від загальних показів кампанії; зміни вибірки та порогів позначити.","Перевірити, який показник змінився: перекриття показів, позиція або частка; різні знаменники й сегменти не змішувати в одному висновку.","Зіставити спостереження зі змінами власного таргетингу, доступності реклами та результатами; домен у звіті не доводить бюджету, причин або намірів конкурента.","Маркетолог погоджує подальше дослідження, спостереження або окрему зміну кампанії; сигнал не запускає автоматичної гонки ставок.","Зберегти підстави й рішення, після придатного періоду переглянути зіставний зріз; відсутній конкурентний рядок лишити обмеженням, а не доказом виходу з ринку."],"requirements":["Є доступний звіт аукціонів і достатній обсяг активності в потрібній області.","Є власник інтерпретації, історія налаштувань і погоджене правило порівняння."],"limitations":["Google описує різне охоплення Search, Shopping і Performance Max та пороги доступності; однакового повного звіту для всіх кампаній не обіцяємо.","Показники спільних аукціонів не є часткою ринку, усією рекламною активністю або бюджетом конкурента.","Причинний ефект зміни ставок не доведено цим звітом; запуск і витрати реклами погоджують окремо.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Команда пояснює втрату показів появою конкурента без зіставного звіту. Частку в спільних аукціонах помилково видають за частку ринку або весь бюджет іншого рекламодавця."],"synonyms":["конкуренти у рекламному аукціоні","зміна перекриття рекламних показів","порівняння звітів аукціонів реклами"],"search_queries":["як перевірити зміни конкуренції у рекламних аукціонах без плутанини з часткою ринку"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/google-ads/answer/2579754?hl=en","title":"Google Ads: зіставлення учасників рекламних аукціонів","checked_at":"2026-10-12","supports":"Описано показники спільних аукціонів, різні знаменники, сегменти й пороги доступності. Погоджений перегляд причин і дій — редакційна модель."},{"type":"inferred_pattern","title":"Редакційна модель перевірки контексту й дозволеного використання","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують можливості продуктів; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"advertising-auction-competition-review-tracked","title":"Контроль із підтвердженням результату","description":"Маркетолог отримує пояснену зміну конкуренції в доступних аукціонах і погоджує доречну дію без автоматичного підвищення ставок.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Перекриття показів із доменом зросло, але команда також змінила власний таргетинг. Маркетолог зберіг обидві підстави й призначив зіставний перегляд без висновку про бюджет конкурента.","implementation_methods":["Зберігати зіставні конкурентні зрізи з областю, сегментами й межами даних.","Передавати пояснену зміну маркетологу для рішення й наступної перевірки."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є доступний звіт аукціонів і достатній обсяг активності в потрібній області.","Є власник інтерпретації, історія налаштувань і погоджене правило порівняння."],"limitations":["Google описує різне охоплення Search, Shopping і Performance Max та пороги доступності; однакового повного звіту для всіх кампаній не обіцяємо.","Показники спільних аукціонів не є часткою ринку, усією рекламною активністю або бюджетом конкурента.","Причинний ефект зміни ставок не доведено цим звітом; запуск і витрати реклами погоджують окремо."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0534","reason":"Відомості про продукт конкурента для угоди не є показниками рекламних аукціонів."},{"type":"related","target_id":"AUT-0520","reason":"Конкуренція власних пошукових сторінок має інший об’єкт і джерело."},{"type":"related","target_id":"AUT-0518","reason":"Зміна бюджету потребує окремого рішення щодо погодженого плану."}],"configurator_questions":[{"id":"advertising-auction-competition-review-segments","question":"Чи треба зіставляти кілька типів кампаній або пристроїв?","help_text":"Збережіть окремі показники, знаменники й охоплення кожного зрізу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Збережіть окремі показники, знаменники й охоплення кожного зрізу."}]},{"id":"advertising-auction-competition-review-changes","question":"Чи історія налаштувань і результати надходять із кількох джерел?","help_text":"Перевірте час змін і придатність порівнюваних періодів.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Перевірте час змін і придатність порівнюваних періодів."}]}]}];
